	(10, 4, 2, '', '<body><section id="portfolio" class="page-section portfolio"><div class="container"><!-- Portfolio Section Heading--><h2 class="page-section-heading text-center text-uppercase text-secondary mb-0">Portfolio</h2><!-- Icon Divider--><div class="divider-custom"><div class="divider-custom-line"></div><div class="divider-custom-icon"><i class="fas fa-star"></i></div><div class="divider-custom-line"></div></div><!-- Portfolio Grid Items--><div class="row justify-content-center"><!-- Portfolio Item 1--><div class="col-md-6 col-lg-4 mb-5"><div data-bs-toggle="modal" data-bs-target="#portfolioModal1" class="portfolio-item mx-auto"><div class="portfolio-item-caption d-flex align-items-center justify-content-center h-100 w-100" id="id9yj"><div class="portfolio-item-caption-content text-center text-white"><i class="fas fa-plus fa-3x"></i></div></div><img src="assets/img/portfolio/cabin.png" alt="..." class="img-fluid"/></div></div><!-- Portfolio Item 2--><div class="col-md-6 col-lg-4 mb-5"><div data-bs-toggle="modal" data-bs-target="#portfolioModal2" class="portfolio-item mx-auto"><div class="portfolio-item-caption d-flex align-items-center justify-content-center h-100 w-100" id="i2gj1"><div class="portfolio-item-caption-content text-center text-white"><i class="fas fa-plus fa-3x"></i></div></div><img src="assets/img/portfolio/cake.png" alt="..." class="img-fluid"/></div></div><!-- Portfolio Item 3--><div class="col-md-6 col-lg-4 mb-5"><div data-bs-toggle="modal" data-bs-target="#portfolioModal3" class="portfolio-item mx-auto"><div class="portfolio-item-caption d-flex align-items-center justify-content-center h-100 w-100"><div class="portfolio-item-caption-content text-center text-white"><i class="fas fa-plus fa-3x"></i></div></div><img src="assets/img/portfolio/circus.png" alt="..." class="img-fluid"/></div></div><!-- Portfolio Item 4--><div class="col-md-6 col-lg-4 mb-5 mb-lg-0"><div data-bs-toggle="modal" data-bs-target="#portfolioModal4" class="portfolio-item mx-auto"><div class="portfolio-item-caption d-flex align-items-center justify-content-center h-100 w-100" id="i2h2l"><div class="portfolio-item-caption-content text-center text-white"><i class="fas fa-plus fa-3x"></i></div></div><img src="assets/img/portfolio/game.png" alt="..." class="img-fluid"/></div></div><!-- Portfolio Item 5--><div class="col-md-6 col-lg-4 mb-5 mb-md-0"><div data-bs-toggle="modal" data-bs-target="#portfolioModal5" class="portfolio-item mx-auto"><div class="portfolio-item-caption d-flex align-items-center justify-content-center h-100 w-100"><div class="portfolio-item-caption-content text-center text-white"><i class="fas fa-plus fa-3x"></i></div></div><img src="assets/img/portfolio/safe.png" alt="..." class="img-fluid"/></div></div><!-- Portfolio Item 6--><div class="col-md-6 col-lg-4"><div data-bs-toggle="modal" data-bs-target="#portfolioModal6" class="portfolio-item mx-auto"><div class="portfolio-item-caption d-flex align-items-center justify-content-center h-100 w-100"><div class="portfolio-item-caption-content text-center text-white"><i class="fas fa-plus fa-3x"></i></div></div><img src="assets/img/portfolio/submarine.png" alt="..." class="img-fluid"/></div></div></div></div></section><!-- About Section--><section id="about" class="page-section bg-primary text-white mb-0"><div class="container"><!-- About Section Heading--><h2 class="page-section-heading text-center text-uppercase text-white">About</h2><!-- Icon Divider--><div class="divider-custom divider-light"><div class="divider-custom-line"></div><div class="divider-custom-icon"><i class="fas fa-star"></i></div><div class="divider-custom-line"></div></div><!-- About Section Content--><div class="row"><div class="col-lg-4 ms-auto"><p class="lead">Freelancer is a free bootstrap theme created by Start Bootstrap. The download includes the complete source files including HTML, CSS, and JavaScript as well as optional SASS stylesheets for easy customization.</p></div><div class="col-lg-4 me-auto"><p class="lead">You can create your own custom avatar for the masthead, change the icon in the dividers, and add your email address to the contact form to make it fully functional!</p></div></div><!-- About Section Button--><div class="text-center mt-4"><a href="https://startbootstrap.com/theme/freelancer/" class="btn btn-xl btn-outline-light"><i class="fas fa-download me-2"></i>\r\n                        Free Download!\r\n                    </a></div></div></section><!-- Contact Section--><section id="contact" class="page-section"><div class="container"><!-- Contact Section Heading--><h2 class="page-section-heading text-center text-uppercase text-secondary mb-0">Contact Me</h2><!-- Icon Divider--><div class="divider-custom"><div class="divider-custom-line"></div><div class="divider-custom-icon"><i class="fas fa-star"></i></div><div class="divider-custom-line"></div></div><!-- Contact Section Form--><div class="row justify-content-center"><div class="col-lg-8 col-xl-7"><!-- * * * * * * * * * * * * * * *--><!-- * * SB Forms Contact Form * *--><!-- * * * * * * * * * * * * * * *--><!-- This form is pre-integrated with SB Forms.--><!-- To make this form functional, sign up at--><!-- https://startbootstrap.com/solution/contact-forms--><!-- to get an API token!--><form method="get" id="contactForm" data-sb-form-api-token="API_TOKEN"><!-- Name input--><div class="form-floating mb-3"><input type="text" id="name" placeholder="Enter your name..." data-sb-validations="required" class="form-control"/><label for="name">Full name</label><div data-sb-feedback="name:required" class="invalid-feedback">A name is required.</div></div><!-- Email address input--><div class="form-floating mb-3"><input type="email" id="email" placeholder="name@example.com" data-sb-validations="required,email" class="form-control"/><label for="email">Email address</label><div data-sb-feedback="email:required" class="invalid-feedback">An email is required.</div><div data-sb-feedback="email:email" class="invalid-feedback">Email is not valid.</div></div><!-- Phone number input--><div class="form-floating mb-3"><input type="tel" id="phone" placeholder="(123) 456-7890" data-sb-validations="required" class="form-control"/><label for="phone">Phone number</label><div data-sb-feedback="phone:required" class="invalid-feedback">A phone number is required.</div></div><!-- Message input--><div class="form-floating mb-3"><textarea id="message" type="text" placeholder="Enter your message here..." data-sb-validations="required" class="form-control"></textarea><label for="message">Message</label><div data-sb-feedback="message:required" class="invalid-feedback">A message is required.</div></div><!-- Submit success message--><!----><!-- This is what your users will see when the form--><!-- has successfully submitted--><div id="submitSuccessMessage" class="d-none"><div class="text-center mb-3"><div class="fw-bolder">Form submission successful!</div>\r\n                                    To activate this form, sign up at\r\n                                    <br/><a href="https://startbootstrap.com/solution/contact-forms">https://startbootstrap.com/solution/contact-forms</a></div></div><!-- Submit error message--><!----><!-- This is what your users will see when there is--><!-- an error submitting the form--><div id="submitErrorMessage" class="d-none"><div class="text-center text-danger mb-3">Error sending message!</div></div><!-- Submit Button--><button type="submit" id="submitButton" class="btn btn-primary btn-xl disabled">Send</button></form></div></div></div></section></body>', '* { box-sizing: border-box; } body {margin: 0;}:root{--bs-blue:#0d6efd;--bs-indigo:#6610f2;--bs-purple:#6f42c1;--bs-pink:#d63384;--bs-red:#dc3545;--bs-orange:#fd7e14;--bs-yellow:#ffc107;--bs-green:#198754;--bs-teal:#1abc9c;--bs-cyan:#0dcaf0;--bs-black:#000;--bs-white:#fff;--bs-gray:#6c757d;--bs-gray-dark:#343a40;--bs-gray-100:#f8f9fa;--bs-gray-200:#e9ecef;--bs-gray-300:#dee2e6;--bs-gray-400:#ced4da